w:r.w:t:
clear; clc; close all;
set(groot, 'defaultFigureColor', 'w', 'defaultAxesColor', 'w', ...
    'defaultAxesFontName', 'Times New Roman', 'defaultAxesFontSize', 9, ...
    'defaultLineLineWidth', 1.2);

% No hay números aleatorios en este código, por eso el resultado es igual en
% cualquier computadora y no hace falta fijar una semilla.

P  = caso_base();
T0 = estacionario(P, P.mcp_base);
fprintf('C [J/K]: Cca = %.2f | Csurf = %.1f | Cins = %.1f\n', P.C);
fprintf('T_Hex = %.2f °C (Ec. 4 con Tins,ss = 37 °C: %.2f °C)\n', P.THex, thex_para(P, 37));
fprintf('mcp de la apertura = %.2f W/K | 1/Ria = %.1f W/K\n', P.mcp_open, 1/P.R.Ria);
fprintf('Estacionario base: Tca = %.2f | Tsurf = %.2f | Tins = %.2f °C\n', T0);

% Columnas: E [V], (T_H - T_ca), (T_ca - T_surf), (T_surf - T_ins), (T_ins - T_amb) en °C
% y R_Hex, R_ca-surf, R_surf-ins, R_ins-amb en K/W (Tablas 4 y 5 del artículo base)
ensayos = [15.1 0.89 1.45 0.85 3.04 0.010 0.018 0.011 0.043;
           20.1 1.63 2.66 1.57 5.58 0.020 0.034 0.020 0.072;
           25.0 2.58 4.19 2.47 8.79 0.030 0.055 0.032 0.116];
dif = zeros(3,3);
fprintf('\nTABLA 3 (publicado / modelo)\n');
for e = 1:size(ensayos,1)
    d = ensayos(e,:);
    pub = P.Tamb + [d(5)+d(4)+d(3), d(5)+d(4), d(5)];   % [T_ca, T_surf, T_ins] publicadas
    Q = P;
    Q.R = struct('Rhex',d(6), 'Rcs',d(7), 'Rsi',d(8), 'Ria',d(9));
    Q.THex = pub(1) + 0.5*d(2);                         % T_Hex = T_ca + 0.5 (T_H - T_ca)
    modelo = estacionario(Q, 0)';
    dif(e,:) = abs(modelo - pub);
    fprintf('E = %4.1f V | T_Hex = %.2f | Tca %.2f/%.2f | Tsurf %.2f/%.2f | Tins %.2f/%.2f\n', ...
            d(1), Q.THex, pub(1), modelo(1), pub(2), modelo(2), pub(3), modelo(3));
end
fprintf('Diferencia entre ensayos (mín - máx): Tca %.2f-%.2f | Tsurf %.2f-%.2f | Tins %.2f-%.2f °C\n', ...
        min(dif(:,1)), max(dif(:,1)), min(dif(:,2)), max(dif(:,2)), min(dif(:,3)), max(dif(:,3)));
fprintf('Caso base frente al ensayo de 25 V: %.2f | %.2f | %.2f °C\n', ...
        abs(T0(1)-(P.Tamb+8.79+2.47+4.19)), abs(T0(2)-(P.Tamb+8.79+2.47)), abs(T0(3)-(P.Tamb+8.79)));

conjuntos = {rmin(), P.R, rmax()};
etiqueta  = {'mínima', 'media', 'máxima'};
fprintf('\n');
for k = 1:3
    Q = P;  Q.R = conjuntos{k};
    A = sistema(Q, Q.mcp_base);
    lam = sort(real(eig(A)));
    fprintf('R %-7s: lambda = [%.4f %.4f %.4f] 1/s | tau = [%.2f %.2f %.2f] s | rigidez = %.1f\n', ...
            etiqueta{k}, lam, -1./lam, lam(1)/lam(3));
    fprintf('           h_c(Heun) = %.3f s | h_c(RK4) = %.3f s\n', ...
            paso_critico('heun', Q), paso_critico('rk4', Q));
end
hc_heun = paso_critico('heun', P);
hc_rk4  = paso_critico('rk4', P);

t  = (0:0.1:250)';
Te = solucion_exacta(P, T0, t);
[~, ic] = min(abs(t - P.t_close));
fprintf('\nDescenso al cerrar: Tca = %.3f | Tsurf = %.3f | Tins = %.3f °C\n', T0' - Te(ic,:));
[~, M] = corre_caso(P);
Tab   = estacionario(P, P.mcp_open);
asint = T0(3) - Tab(3);
fprintf('dTmax = %.3f °C (%.1f %% del asintótico %.3f) | t90 = %.1f s | I = %.1f K*s\n', ...
        M.dmax, 100*M.dmax/asint, asint, M.t90, M.I);

col = [0.12 0.31 0.61; 0.83 0.46 0.17; 0.16 0.62 0.36; 0.56 0.27 0.68];
f1 = figure('Units','centimeters','Position',[2 2 8.5 5.2]); hold on; box on; grid on;
patch([60 120 120 60], [-0.85 -0.85 0.05 0.05], [0.88 0.88 0.88], ...
      'EdgeColor','none', 'HandleVisibility','off');
for i = 1:3, plot(t, Te(:,i) - T0(i), 'Color', col(i,:)); end
xlabel('Tiempo (s)'); ylabel('Desviación (°C)'); xlim([0 250]); ylim([-0.85 0.05]);
legend({'T_{ca}', 'T_{surf}', 'T_{ins}'}, 'Location','southeast', 'Box','off');
exportgraphics(f1, 'fig1_respuesta_base.pdf', 'ContentType','vector');

metodos = {'heun', 'rk4', 'trapecio', 'euler_atras'};
nombres = {'Euler mejorado', 'RK4', 'Trapecio', 'Euler hacia atrás'};
Tfrio = P.Tamb*ones(3,1);                 % arranque en frío: excita todos los modos
hs  = 0.5*2.^-(0:7);
err = zeros(numel(metodos), numel(hs));
fprintf('\n');
for m = 1:numel(metodos)
    for k = 1:numel(hs)
        [t, T] = integrar(metodos{m}, P, Tfrio, hs(k), P.Tf);
        Te = solucion_exacta(P, Tfrio, t);
        err(m,k) = max(abs(T(:) - Te(:)));
    end
    fprintf('%-12s orden p = %.2f | error con h = %.4f s: %.2e °C\n', ...
            metodos{m}, log2(err(m,end-1)/err(m,end)), hs(end), err(m,end));
end

% Simulaciones con h cerca del paso crítico (h = 60/N para alinear la malla)
hc = [hc_heun hc_rk4];
fprintf('\n');
for m = 1:2
    for fac = [0.9 1.1]
        if fac < 1, N = floor(60/(hc(m)*fac)); else, N = ceil(60/(hc(m)*fac)); end
        [~, T] = integrar(metodos{m}, P, Tfrio, 60/N, P.Tf);
        fprintf('%-5s h = %.4f s (h/h_c = %.3f): max|T| = %.3g °C\n', ...
                metodos{m}, 60/N, (60/N)/hc(m), max(abs(T(:))));
    end
end

fprintf('\nTABLA 4: método | h | pasos | operaciones | error\n');
for m = 1:numel(metodos)
    if any(strcmp(metodos{m}, {'heun','rk4'})), hc_m = paso_critico(metodos{m}, P); else, hc_m = inf; end
    for N = 1:5000
        h = 60/N;
        if h >= hc_m, continue; end        % los explícitos divergen por encima de h_c
        [t, T] = integrar(metodos{m}, P, T0, h, P.Tf);
        e = max(max(abs(T - solucion_exacta(P, T0, t))));
        if e <= 1e-3, break; end
    end
    nPasos = round(P.Tf/h);
    ops = nPasos*[2 4 1 1];  ops = ops(m);   % Heun: 2 evaluaciones por paso, RK4: 4, implícitos: 1 sistema
    fprintf('%-12s h = %.3f s | pasos = %d | operaciones = %d | error = %.1e\n', ...
            metodos{m}, h, nPasos, ops, e);
end

fprintf('\nTrapecio desde el estacionario (perturbación): error máximo\n');
for h = [0.5 1 2 5 10 15 20]
    [t, T] = integrar('trapecio', P, T0, h, P.Tf);
    fprintf('  h = %4.1f s: %.2e °C\n', h, max(max(abs(T - solucion_exacta(P, T0, t)))));
end

lam_max = min(real(eig(sistema(P, P.mcp_base))));   % valor propio de mayor módulo
fprintf('\nArranque en frío: T_ca sobre T_Hex = %.2f °C\n', P.THex);
for h = [0.5 1 2 5 10]
    [~, Tt] = integrar('trapecio',    P, Tfrio, h, P.Tf);
    [~, Tb] = integrar('euler_atras', P, Tfrio, h, P.Tf);
    z = h*lam_max;
    fprintf('  h = %4.1f s: trapecio %+.2f | Euler atrás %+.2f | h*lambda = %.1f | R_trap = %.2f | R_atrás = %.2f\n', ...
            h, max(Tt(:,1)) - P.THex, max(Tb(:,1)) - P.THex, z, (1 + z/2)/(1 - z/2), 1/(1 - z));
end

% Figura 2: (a) convergencia, (b) oscilación del trapecio
f2 = figure('Units','centimeters','Position',[2 2 17.5 6]);
subplot(1,2,1); mk = {'o','s','^','v'};
for m = 1:4, loglog(hs, err(m,:), ['-' mk{m}], 'Color', col(m,:), 'MarkerSize', 4); hold on; end
grid on; xlabel('Paso de tiempo h (s)'); ylabel('Error máximo (°C)');
legend(nombres, 'Location','southeast', 'Box','off'); title('(a)');
subplot(1,2,2);
tt = linspace(0,20,801)';  Tex = solucion_exacta(P, Tfrio, tt);
[t2, Tt] = integrar('trapecio',    P, Tfrio, 2, 100);
[~,  Tb] = integrar('euler_atras', P, Tfrio, 2, 100);
s = t2 <= 20;
plot(tt, Tex(:,1), 'k', 'LineWidth', 1.4); hold on; grid on;
plot(t2(s), Tt(s,1), '--o', 'Color', col(2,:), 'MarkerSize', 4);
plot(t2(s), Tb(s,1), ':s',  'Color', col(3,:), 'MarkerSize', 4);
yline(P.THex, '-.', 'T_{Hex}', 'Color', [0.4 0.4 0.4], 'HandleVisibility','off');
xlabel('Tiempo (s)'); ylabel('T_{ca} (°C)'); xlim([0 20]); title('(b)');
legend({'Exacta','Trapecio, h = 2 s','Euler hacia atrás, h = 2 s'}, 'Location','southeast', 'Box','off');
exportgraphics(f2, 'fig2_convergencia.pdf', 'ContentType','vector');

% dTmax con T_Hex fija; dTmax* con T_Hex reajustada para Tins,ss = 37 °C
casos = {'Caso base', 'Ria=0.043', 'Ria=0.116', 'Rsi=0.011', 'Rsi=0.032', ...
         'Rcs=0.018', 'Rcs=0.055', 'Csurf -50%', 'Csurf +50%', 'Cins -20%', ...
         'Cins +20%', 'THex -2 K', 'THex +2 K', 'R minimas', 'R maximas'};
res = zeros(numel(casos), 5);               % Tss, dTmax, dTmax*, t90, I
dt90 = 0;                                   % mayor diferencia de t90 entre T_Hex fija y reajustada
fprintf('\nTABLA 5\n%-11s %7s %7s %8s %6s %6s\n', 'Caso', 'Tins,ss', 'dTmax', 'dTmax*', 't90', 'I');
for c = 1:numel(casos)
    Q = P;  reajusta = true;
    switch casos{c}
        case 'Ria=0.043',   Q.R.Ria = 0.043;
        case 'Ria=0.116',   Q.R.Ria = 0.116;
        case 'Rsi=0.011',   Q.R.Rsi = 0.011;
        case 'Rsi=0.032',   Q.R.Rsi = 0.032;
        case 'Rcs=0.018',   Q.R.Rcs = 0.018;
        case 'Rcs=0.055',   Q.R.Rcs = 0.055;
        case 'Csurf -50%',  Q.C(2) = 0.5*P.C(2);
        case 'Csurf +50%',  Q.C(2) = 1.5*P.C(2);
        case 'Cins -20%',   Q.C(3) = 0.8*P.C(3);
        case 'Cins +20%',   Q.C(3) = 1.2*P.C(3);
        case 'THex -2 K',   Q.THex = P.THex - 2;  reajusta = false;
        case 'THex +2 K',   Q.THex = P.THex + 2;  reajusta = false;
        case 'R minimas',   Q.R = rmin();
        case 'R maximas',   Q.R = rmax();
    end
    [Tss, M] = corre_caso(Q);
    if reajusta
        Q2 = Q;  Q2.THex = thex_para(Q2, 37);
        [~, M2] = corre_caso(Q2);  dstar = M2.dmax;
        dt90 = max(dt90, abs(M2.t90 - M.t90));
    else
        dstar = NaN;                        % reajustar T_Hex anularía la variación
    end
    res(c,:) = [Tss M.dmax dstar M.t90 M.I];
    fprintf('%-11s %7.2f %7.3f %8.3f %6.1f %6.1f\n', casos{c}, res(c,:));
end
% Cambio porcentual respecto al caso base
pct = 100*(res(:,[2 3 4]) ./ res(1,[2 3 4]) - 1);
fprintf('\nCambio respecto al caso base (%%): dTmax | dTmax* | t90\n');
for c = 2:numel(casos)
    if isnan(pct(c,2))
        fprintf('%-11s %+6.1f %6s %+6.1f\n', casos{c}, pct(c,1), '---', pct(c,3));
    else
        fprintf('%-11s %+6.1f %+6.1f %+6.1f\n', casos{c}, pct(c,:));
    end
end
fprintf('Diferencia máxima de t90 entre T_Hex fija y reajustada: %.1f s\n', dt90);

dtmax = [];                                  % instante del máximo menos instante de cierre
fprintf('\nVelocidad v [m/s] | mcp [W/K] | dTmax | t90\n');
v = [0.05 0.10 0.20];
for k = 1:3
    Q = P;  Q.mcp_open = P.mcp_open*v(k)/0.10;
    [~, M] = corre_caso(Q);
    dtmax(end+1) = M.tmax - Q.t_close;
    fprintf('%.2f | %.2f | %.3f | %.1f\n', v(k), Q.mcp_open, M.dmax, M.t90);
end
fprintf('Duración [s] | dTmax | I [K*s] | t90\n');
dur = [15 30 60 120];
for k = 1:4
    Q = P;  Q.t_close = 60 + dur(k);
    [~, M] = corre_caso(Q);
    dtmax(end+1) = M.tmax - Q.t_close;
    fprintf('%3d | %.3f | %.1f | %.1f\n', dur(k), M.dmax, M.I, M.t90);
end
fprintf('Tamb [°C] | T_Hex | dTmax | t90 | dTmax/(Tins,ss - Tamb)\n');
Tas = [20 24 28];
for k = 1:3
    Q = P;  Q.Tamb = Tas(k);  Q.THex = thex_para(Q, 37);
    [~, M] = corre_caso(Q);
    dtmax(end+1) = M.tmax - Q.t_close;
    fprintf('%4d | %.2f | %.3f | %.1f | %.4f\n', Tas(k), Q.THex, M.dmax, M.t90, M.dmax/(37 - Tas(k)));
end
fprintf('El descenso máximo ocurrió al cerrar en todos los casos: %d\n', all(abs(dtmax) < 0.15));

f3 = figure('Units','centimeters','Position',[2 2 17.5 5.6]);
subplot(1,3,1); hold on; box on; grid on;
patch([60 120 120 60], [0 0 1.6 1.6], [0.88 0.88 0.88], 'EdgeColor','none', 'HandleVisibility','off');
for k = 1:3
    Q = P;  Q.mcp_open = P.mcp_open*v(k)/0.10;  [t, d] = caida(Q);
    plot(t, d, 'Color', col(k,:));
end
legend({'0.05 m/s', '0.10 m/s', '0.20 m/s'}, 'Box','off'); title('(a) Velocidad del aire');
xlabel('Tiempo (s)'); ylabel('Descenso de T_{ins} (°C)'); xlim([0 300]);
subplot(1,3,2); hold on; box on; grid on;
for k = 1:4
    Q = P;  Q.t_close = 60 + dur(k);  [t, d] = caida(Q);
    plot(t, d, 'Color', col(k,:));
end
xline(60, 'Color', [0.5 0.5 0.5], 'HandleVisibility','off');
legend({'15 s','30 s','60 s','120 s'}, 'Box','off'); title('(b) Duración de la apertura');
xlabel('Tiempo (s)'); xlim([0 300]);
subplot(1,3,3); hold on; box on; grid on;
patch([60 120 120 60], [0 0 1.6 1.6], [0.88 0.88 0.88], 'EdgeColor','none', 'HandleVisibility','off');
for k = 1:3
    Q = P;  Q.Tamb = Tas(k);  Q.THex = thex_para(Q, 37);  [t, d] = caida(Q);
    plot(t, d, 'Color', col(k,:));
end
legend({'20 °C', '24 °C', '28 °C'}, 'Box','off'); title('(c) Temperatura ambiente');
xlabel('Tiempo (s)'); xlim([0 300]);
exportgraphics(f3, 'fig3_apertura.pdf', 'ContentType','vector');

function P = caso_base()
% Parámetros del caso base (Rincón Casado et al., 2021)
    rho = 1.21; cp = 1007;
    P.C = [rho*0.0315*cp; 25*(0.5*0.4*0.03)*1674; rho*0.1715*cp];    % [Cca; Csurf; Cins] en J/K
    P.R = struct('Rhex',0.020,'Rcs',0.036,'Rsi',0.021,'Ria',0.077);   % K/W, medias de sus Tablas 4 y 5
    P.THex = 44.83;  P.Tamb = 28;
    P.mcp_base = 0;  P.mcp_open = rho*(0.17*0.13)*0.10*cp;            % 2.69 W/K con v = 0.10 m/s
    P.t_open = 60;  P.t_close = 120;  P.Tf = 300;
end

function R = rmin()
% Resistencias mínimas de las Tablas 4 y 5 del artículo base
    R = struct('Rhex',0.010,'Rcs',0.018,'Rsi',0.011,'Ria',0.043);
end

function R = rmax()
% Resistencias máximas de las Tablas 4 y 5 del artículo base
    R = struct('Rhex',0.030,'Rcs',0.055,'Rsi',0.032,'Ria',0.116);
end

function THex = thex_para(P, Tset)
% Ec. (4): T_Hex que da T_ins,ss = Tset con los accesos cerrados
    R = P.R;  Rtot = 0.5*R.Rhex + R.Rcs + R.Rsi + R.Ria;
    THex = P.Tamb + (Tset - P.Tamb)*Rtot/R.Ria;
end

function [A, b] = sistema(P, mcp)
% Forma matricial dT/dt = A*T + b, con T = [T_ca; T_surf; T_ins]
    R = P.R;
    gh = 1/(0.5*R.Rhex);  gcs = 1/R.Rcs;  gsi = 1/R.Rsi;  gia = 1/R.Ria + mcp;
    K = [-(gh+gcs), gcs, 0; gcs, -(gcs+gsi), gsi; 0, gsi, -(gsi+gia)];
    A = K ./ P.C;
    b = [gh*P.THex; 0; gia*P.Tamb] ./ P.C;
end

function Ts = estacionario(P, mcp)
% Estado estacionario para un caudal dado: 0 = A*Ts + b
    [A, b] = sistema(P, mcp);  Ts = -A \ b;
end

function [t, T] = integrar(metodo, P, T0, h, Tf)
% Avanza con Euler mejorado, RK4, trapecio o Euler hacia atrás sobre una malla
% uniforme. h tiene que dividir a t_open y t_close para que A y b sean
% constantes dentro de cada paso.
    assert(abs(P.t_open/h - round(P.t_open/h)) < 1e-9 && ...
           abs(P.t_close/h - round(P.t_close/h)) < 1e-9, ...
           'h debe dividir a t_open y t_close');
    n = round(Tf/h);  t = (0:n)'*h;  T = zeros(n+1,3);  T(1,:) = T0(:)';
    [Ac, bc] = sistema(P, P.mcp_base);  [Aa, ba] = sistema(P, P.mcp_open);  I3 = eye(3);
    for k = 1:n
        tm = t(k) + 0.5*h;
        if tm >= P.t_open && tm < P.t_close, A = Aa; b = ba; else, A = Ac; b = bc; end
        x = T(k,:)';
        switch metodo
            case 'heun'
                k1 = A*x + b;  k2 = A*(x + h*k1) + b;  xn = x + 0.5*h*(k1 + k2);
            case 'rk4'
                k1 = A*x + b;  k2 = A*(x + 0.5*h*k1) + b;
                k3 = A*(x + 0.5*h*k2) + b;  k4 = A*(x + h*k3) + b;
                xn = x + h/6*(k1 + 2*k2 + 2*k3 + k4);
            case 'trapecio'
                xn = (I3 - 0.5*h*A) \ ((I3 + 0.5*h*A)*x + h*b);
            case 'euler_atras'
                xn = (I3 - h*A) \ (x + h*b);
        end
        T(k+1,:) = xn';
    end
end

function Te = solucion_exacta(P, T0, t)
% Solución exacta por tramos: T = Ts + exp(A (t - ta)) (Ta - Ts), con A
% diagonalizada a través de su versión simétrica (C^(1/2) A C^(-1/2))
    t = t(:);  ta = [0, P.t_open, P.t_close];  tb = [P.t_open, P.t_close, inf];
    mc = [P.mcp_base, P.mcp_open, P.mcp_base];
    Te = zeros(numel(t),3);  x0 = T0(:);  Ds = sqrt(P.C);
    for s = 1:3
        [A, b] = sistema(P, mc(s));  Ts = -A \ b;
        S = (A .* P.C) ./ (Ds*Ds');  S = (S + S')/2;  [Q, L] = eig(S);  lam = diag(L);
        z = Q' * (Ds .* (x0 - Ts));  idx = (t >= ta(s)) & (t < tb(s));
        if any(idx)
            tau = (t(idx) - ta(s))';
            Te(idx,:) = (Ts + (1./Ds) .* (Q * (exp(lam*tau) .* z)))';
        end
        if s < 3, x0 = Ts + (1./Ds) .* (Q * (exp(lam*(tb(s) - ta(s))) .* z)); end
    end
end

function hc = paso_critico(metodo, P)
% Paso máximo estable: bisección sobre el radio espectral de la matriz de amplificación
    As = {sistema(P, P.mcp_base), sistema(P, P.mcp_open)};
    lo = 1e-3;  hi = 5;
    for it = 1:80
        h = 0.5*(lo + hi);  r = 0;
        for j = 1:2
            Z = h*As{j};  I3 = eye(3);
            if strcmp(metodo, 'heun'), G = I3 + Z + Z^2/2;
            else, G = I3 + Z + Z^2/2 + Z^3/6 + Z^4/24; end
            r = max(r, max(abs(eig(G))));
        end
        if r <= 1, lo = h; else, hi = h; end
    end
    hc = lo;
end

function [Tss, M] = corre_caso(Q)
% Métricas de la perturbación con la solución exacta: descenso máximo, su instante, t90 e integral
    T0 = estacionario(Q, Q.mcp_base);  Tss = T0(3);
    t = (0:0.1:Q.Tf)';  Te = solucion_exacta(Q, T0, t);
    d = T0(3) - Te(:,3);  [~, ic] = min(abs(t - Q.t_close));  dc = d(ic);
    j = find(t >= Q.t_close & d <= 0.1*dc, 1);
    M.dmax = max(d);  M.t90 = t(j) - Q.t_close;  M.I = trapz(t, d);
    M.tmax = t(find(d == M.dmax, 1));
end

function [t, d] = caida(Q)
% Descenso de T_ins respecto a su estado estacionario previo
    T0 = estacionario(Q, Q.mcp_base);
    t = (0:0.1:Q.Tf)';  Te = solucion_exacta(Q, T0, t);  d = T0(3) - Te(:,3);
end
